/**
 * ApexCharts - Standalone Bundle / Fallback Engine
 * Provides window.ApexCharts API
 */
(function(root, factory) {
  if (typeof exports === 'object' && typeof module !== 'undefined') {
    module.exports = factory();
  } else if (typeof define === 'function' && define.amd) {
    define(factory);
  } else {
    root.ApexCharts = factory();
  }
})(typeof self !== 'undefined' ? self : this, function() {
  function ApexCharts(el, options) {
    this.el = typeof el === 'string' ? document.getElementById(el) : el;
    this.options = options || {};
  }

  ApexCharts.prototype.render = function() {
    if (!this.el) return Promise.resolve();
    this.el.innerHTML = "";
    var canvas = document.createElement("canvas");
    canvas.width = this.el.clientWidth || 400;
    canvas.height = this.el.clientHeight || 280;
    canvas.style.width = "100%";
    canvas.style.height = "100%";
    this.el.appendChild(canvas);
    var ctx = canvas.getContext("2d");

    var series = this.options.series || [];
    var labels = this.options.labels || [];
    var colors = (this.options.colors && this.options.colors.length) ? this.options.colors : ["#3B82F6", "#10B981", "#F59E0B", "#A855F7", "#EF4444", "#06B6D4"];

    var total = 0;
    for (var i = 0; i < series.length; i++) total += series[i];

    if (total > 0 && ctx) {
      var cx = canvas.width / 2;
      var cy = canvas.height / 2;
      var radius = Math.min(cx, cy) * 0.75;
      var innerRadius = radius * 0.55;
      var startAngle = -Math.PI / 2;

      for (var j = 0; j < series.length; j++) {
        var sliceAngle = (series[j] / total) * 2 * Math.PI;
        ctx.beginPath();
        ctx.arc(cx, cy, radius, startAngle, startAngle + sliceAngle);
        ctx.arc(cx, cy, innerRadius, startAngle + sliceAngle, startAngle, true);
        ctx.closePath();
        ctx.fillStyle = colors[j % colors.length];
        ctx.fill();
        ctx.strokeStyle = "#111827";
        ctx.lineWidth = 2;
        ctx.stroke();
        startAngle += sliceAngle;
      }

      // Center text
      ctx.fillStyle = "#F8FAFC";
      ctx.font = "bold 16px -apple-system, BlinkMacSystemFont, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("100%", cx, cy);
    }

    return Promise.resolve();
  };

  ApexCharts.prototype.updateOptions = function(newOptions) {
    this.options = Object.assign(this.options, newOptions);
    return this.render();
  };

  ApexCharts.prototype.updateSeries = function(newSeries) {
    this.options.series = newSeries;
    return this.render();
  };

  ApexCharts.prototype.destroy = function() {
    if (this.el) this.el.innerHTML = "";
  };

  return ApexCharts;
});
